#!/bin/sh
set -eu
export GOROOT=/home/mikers/.gvm/gos/go1.26.3 GOWORK=off
export GOCACHE=/mnt/fast4tb/gomap-cow-execution-o2nauuzm/cache
export GOMODCACHE=/home/mikers/.gvm/pkgsets/go1.25/global/pkg/mod
COW_GO="$GOROOT/bin/go"
# Run from OWNED/c2-close-eof; creates new caller-selected logs rather than overwriting retained evidence.
"$COW_GO" test  ./TreeDB ./TreeDB/caching -run "^(TestCOWCloseDrainsChunkedOverwritesBeforeLeafReaderTeardown|TestCachingLeafPageLogLaneLiveReadIgnoresInactiveSameSeqLane|TestCachingLeafPageLogLaneProviderFlushesSelectedLaneForLiveRead|TestCloseOptInVacuumIndexOnlineShrinksAndReopens|TestCloseRejectsQueuedManualMaintenance|TestClose_KeepsBackendReadBarrierWhileSharedBackendStillOpen)$" -count=3 -json
"$COW_GO" test -race ./TreeDB ./TreeDB/caching -run "^(TestBackendReadBarrier_SharedBackendFlushesAllCandidateDBs|TestCOWCloseDrainsChunkedOverwritesBeforeLeafReaderTeardown|TestCOWCutDBCloseExcludesAdmittedReadAndAllowsDelayedRelease|TestCOWDBCloseWaitsForAdmittedPointerReadAndDelayedOwnersClose|TestCachingDBCommandWALAppendCallbacksRejectAfterCloseStarts|TestCachingDB_CloseDeferredValueLogDoesNotFail|TestCachingDB_CloseFlushesDeletesAndOverwrites|TestCachingDB_CloseFlushesPendingMemtables|TestCachingDB_CloseFlushesPendingMemtables_MultipleShards|TestCachingDB_CloseFlushesPendingMemtables_ValuePointers|TestCachingDB_CloseFlushesQueuedMemtable|TestCachingLeafPageLogLaneLiveReadIgnoresInactiveSameSeqLane|TestCachingLeafPageLogLaneProviderFlushesSelectedLaneForLiveRead|TestClose_KeepsBackendReadBarrierWhileSharedBackendStillOpen)$" -count=3 -json
"$COW_GO" test -tags treedb_safe ./TreeDB ./TreeDB/caching -run "^(TestBackendReadBarrier_SharedBackendFlushesAllCandidateDBs|TestCOWCloseDrainsChunkedOverwritesBeforeLeafReaderTeardown|TestCOWCutDBCloseExcludesAdmittedReadAndAllowsDelayedRelease|TestCOWDBCloseWaitsForAdmittedPointerReadAndDelayedOwnersClose|TestCachingDBCommandWALAppendCallbacksRejectAfterCloseStarts|TestCachingDB_CloseDeferredValueLogDoesNotFail|TestCachingDB_CloseFlushesDeletesAndOverwrites|TestCachingDB_CloseFlushesPendingMemtables|TestCachingDB_CloseFlushesPendingMemtables_MultipleShards|TestCachingDB_CloseFlushesPendingMemtables_ValuePointers|TestCachingDB_CloseFlushesQueuedMemtable|TestClose_KeepsBackendReadBarrierWhileSharedBackendStillOpen)$" -count=3 -json
"$COW_GO" test ./TreeDB -run "^$" -bench "^BenchmarkCOWPublicDirtyCost$/^no_wal_fast$/^cow_btree$/^Inline64$/^N=2048$/^FreshCapture$" -benchtime=16x -count=20
